const response = await fetch('http://localhost:8000/v1/cel/execute', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ script: 'return 42;' })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.post("http://localhost:8000/v1/cel/execute")
    .json(&serde_json::json!({ "script": "return 42;" }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);

const response = await fetch('http://localhost:8000/v1/execute/plugin_name/function_name', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ args: ['query', 10] })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.post("http://localhost:8000/v1/execute/plugin_name/function_name")
    .json(&serde_json::json!({ "args": ["query", 10] }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);
